d3d9:
static BOOL fvf_position_is_blended(DWORD fvf)
{
    DWORD position = fvf & D3DFVF_POSITION_MASK;
    return position >= D3DFVF_XYZB1 && position <= D3DFVF_XYZB5;
}

static BOOL fvf_has_blend_indices(DWORD fvf)
{
    if (fvf & (D3DFVF_LASTBETA_UBYTE4 | D3DFVF_LASTBETA_D3DCOLOR))
        return TRUE;
    return (fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZB5;
}

static BOOL fvf_to_declaration(DWORD fvf, D9WGVertexElement *elements,
        UINT *element_count)
{
    UINT count = 0;
    UINT offset = 0;
    UINT tex_count;
    UINT i;

    if (fvf & D3DFVF_RESERVED0)
        return FALSE;
    if ((fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZ) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT3;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_POSITION;
        elements[count].usage_index = 0;
        ++count;
        offset += 12;
    } else if ((fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZRHW) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT4;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_POSITIONT;
        elements[count].usage_index = 0;
        ++count;
        offset += 16;
    } else if ((fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZW) {
        /* A four-component untransformed position, which only a vertex shader
         * consumes -- unlike XYZRHW it is not pre-transformed. */
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT4;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_POSITION;
        elements[count].usage_index = 0;
        ++count;
        offset += 16;
    } else if (fvf_position_is_blended(fvf)) {
        /* D3DFVF_XYZBn: a float3 position followed by n DWORDs of skinning
         * data. This is the FVF spelling of the same BLENDWEIGHT/BLENDINDICES
         * a vertex declaration states directly, and it used to be refused
         * outright -- so SetFVF was the one entry point where the host's
         * D3DRS_VERTEXBLEND support could not be reached. */
        DWORD blend_dwords = 1u + (((fvf & D3DFVF_POSITION_MASK)
                - D3DFVF_XYZB1) >> 1);
        BOOL has_indices = fvf_has_blend_indices(fvf);
        DWORD weight_count = blend_dwords - (has_indices ? 1u : 0u);

        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT3;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_POSITION;
        elements[count].usage_index = 0;
        ++count;
        offset += 12;

        if (weight_count) {
            /* FLOAT1..FLOAT4 are D3DDECLTYPE 0..3, so the count maps straight
             * onto the enum. weight_count cannot exceed 4: XYZB5 always
             * spends its last DWORD on indices (see fvf_has_blend_indices). */
            elements[count].stream = 0;
            elements[count].offset = (uint16_t)offset;
            elements[count].type = (uint8_t)(D3DDECLTYPE_FLOAT1
                    + (weight_count - 1u));
            elements[count].method = D3DDECLMETHOD_DEFAULT;
            elements[count].usage = D3DDECLUSAGE_BLENDWEIGHT;
            elements[count].usage_index = 0;
            ++count;
            offset += weight_count * 4u;
        }
        if (has_indices) {
            elements[count].stream = 0;
            elements[count].offset = (uint16_t)offset;
            elements[count].type = (fvf & D3DFVF_LASTBETA_D3DCOLOR)
                    ? D3DDECLTYPE_D3DCOLOR : D3DDECLTYPE_UBYTE4;
            elements[count].method = D3DDECLMETHOD_DEFAULT;
            elements[count].usage = D3DDECLUSAGE_BLENDINDICES;
            elements[count].usage_index = 0;
            ++count;
            offset += 4;
        }
    }
    /*
     * No position bits at all is the remaining case, and it is deliberately
     * not an error. A vs_3_0 shader may take its position from somewhere other
     * than the vertex stream -- 3DMark06's SM3.0 particle test drives every
     * particle from a vertex texture fetch and its stream carries nothing but
     * two texture coordinates, so the FVF describing that stream has no
     * position element to declare. Refusing it left the *previous* pass's
     * declaration bound, and the draw was then laid out with that pass's
     * offsets against this pass's 12-byte stride.
     *
     * Only an FVF that describes no attribute whatsoever is refused, below.
     */
    if (fvf & D3DFVF_NORMAL) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT3;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_NORMAL;
        elements[count].usage_index = 0;
        ++count;
        offset += 12;
    }
    if (fvf & D3DFVF_PSIZE) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_FLOAT1;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_PSIZE;
        elements[count].usage_index = 0;
        ++count;
        offset += 4;
    }
    if (fvf & D3DFVF_DIFFUSE) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_D3DCOLOR;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_COLOR;
        elements[count].usage_index = 0;
        ++count;
        offset += 4;
    }
    if (fvf & D3DFVF_SPECULAR) {
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = D3DDECLTYPE_D3DCOLOR;
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_COLOR;
        elements[count].usage_index = 1;
        ++count;
        offset += 4;
    }
    tex_count = (fvf & D3DFVF_TEXCOUNT_MASK) >> D3DFVF_TEXCOUNT_SHIFT;
    if (tex_count > 8)
        return FALSE;
    for (i = 0; i < tex_count; ++i) {
        /*
         * The two bits per set in the FVF's high half are D3DFVF_TEXTUREFORMAT2
         * /3/4/1 in that order -- the encoding is not the component count, so
         * these tables carry it rather than arithmetic. A set is two floats
         * only by default; 1D sets index a lookup table and 3D/4D sets carry
         * projective or cube coordinates, and all three are ordinary D3D9.
         */
        static const uint8_t texcoord_type[4] = {
            D3DDECLTYPE_FLOAT2, D3DDECLTYPE_FLOAT3,
            D3DDECLTYPE_FLOAT4, D3DDECLTYPE_FLOAT1
        };
        static const UINT texcoord_bytes[4] = { 8, 12, 16, 4 };
        DWORD size_bits = (fvf >> (16 + i * 2)) & 0x3u;
        elements[count].stream = 0;
        elements[count].offset = (uint16_t)offset;
        elements[count].type = texcoord_type[size_bits];
        elements[count].method = D3DDECLMETHOD_DEFAULT;
        elements[count].usage = D3DDECLUSAGE_TEXCOORD;
        elements[count].usage_index = (uint8_t)i;
        ++count;
        offset += texcoord_bytes[size_bits];
    }
    if (!count)
        return FALSE;
    *element_count = count;
    return TRUE;
}

d3d8:
static BOOL fvf_position_is_blended(DWORD fvf)
{
    DWORD position = fvf & D3DFVF_POSITION_MASK;
    return position >= D3DFVF_XYZB1 && position <= D3DFVF_XYZB5;
}

static BOOL fvf_has_blend_indices(DWORD fvf)
{
    if (fvf & D3DFVF_LASTBETA_UBYTE4)
        return TRUE;
    return (fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZB5;
}

static BOOL fvf_to_elements(DWORD fvf, D9WGVertexElement *elements,
        UINT max_elements, UINT *element_count)
{
    static const uint8_t texcoord_type[4] = {
        (uint8_t)D3D9DECLTYPE_FLOAT2, (uint8_t)D3D9DECLTYPE_FLOAT3,
        (uint8_t)D3D9DECLTYPE_FLOAT4, (uint8_t)D3D9DECLTYPE_FLOAT1
    };
    static const UINT texcoord_bytes[4] = { 8u, 12u, 16u, 4u };
    UINT count = 0;
    UINT offset = 0;
    UINT tex_count;
    UINT i;

    if (fvf & D3DFVF_RESERVED0)
        return FALSE;

#define D8_PUSH_ELEMENT(element_type, element_usage, element_usage_index) \
    do { \
        if (count >= max_elements || offset > 0xFFFFu) return FALSE; \
        elements[count].stream = 0; \
        elements[count].offset = (uint16_t)offset; \
        elements[count].type = (uint8_t)(element_type); \
        elements[count].method = (uint8_t)D3D9DECLMETHOD_DEFAULT; \
        elements[count].usage = (uint8_t)(element_usage); \
        elements[count].usage_index = (uint8_t)(element_usage_index); \
        ++count; \
    } while (0)

    if ((fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZ) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_POSITION, 0);
        offset += 12;
    } else if ((fvf & D3DFVF_POSITION_MASK) == D3DFVF_XYZRHW) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT4, D3D9DECLUSAGE_POSITIONT, 0);
        offset += 16;
    } else if (fvf_position_is_blended(fvf)) {
        DWORD blend_dwords = 1u + (((fvf & D3DFVF_POSITION_MASK)
                - D3DFVF_XYZB1) >> 1);
        BOOL has_indices = fvf_has_blend_indices(fvf);
        DWORD weight_count = blend_dwords - (has_indices ? 1u : 0u);

        D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_POSITION, 0);
        offset += 12;
        if (weight_count) {
            /* FLOAT1..FLOAT4 are D3DDECLTYPE 0..3, so the weight count maps
             * straight onto the enum. It cannot exceed 4: XYZB5 always spends
             * its last DWORD on indices (see fvf_has_blend_indices). */
            D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT1 + (weight_count - 1u),
                    D3D9DECLUSAGE_BLENDWEIGHT, 0);
            offset += weight_count * 4u;
        }
        if (has_indices) {
            D8_PUSH_ELEMENT(D3D9DECLTYPE_UBYTE4, D3D9DECLUSAGE_BLENDINDICES, 0);
            offset += 4;
        }
    }
    /* No position bits at all is legal and deliberately not an error: a vertex
     * shader may take its position from somewhere other than the stream. Only
     * an FVF describing no attribute whatsoever is refused, below. */
    if (fvf & D3DFVF_NORMAL) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_NORMAL, 0);
        offset += 12;
    }
    if (fvf & D3DFVF_PSIZE) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT1, D3D9DECLUSAGE_PSIZE, 0);
        offset += 4;
    }
    if (fvf & D3DFVF_DIFFUSE) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_D3DCOLOR, D3D9DECLUSAGE_COLOR, 0);
        offset += 4;
    }
    if (fvf & D3DFVF_SPECULAR) {
        D8_PUSH_ELEMENT(D3D9DECLTYPE_D3DCOLOR, D3D9DECLUSAGE_COLOR, 1);
        offset += 4;
    }
    tex_count = (fvf & D3DFVF_TEXCOUNT_MASK) >> D3DFVF_TEXCOUNT_SHIFT;
    if (tex_count > 8)
        return FALSE;
    for (i = 0; i < tex_count; ++i) {
        /* The two bits per set in the FVF's high half are
         * D3DFVF_TEXTUREFORMAT2/3/4/1 in that order -- the encoding is not the
         * component count, which is why these are tables rather than
         * arithmetic. */
        DWORD size_bits = (fvf >> (16u + i * 2u)) & 0x3u;
        D8_PUSH_ELEMENT(texcoord_type[size_bits], D3D9DECLUSAGE_TEXCOORD, i);
        offset += texcoord_bytes[size_bits];
    }
#undef D8_PUSH_ELEMENT

    if (!count)
        return FALSE;
    *element_count = count;
    return TRUE;
}

d3d7:
typedef struct D3D7FVFLayout {
    UINT stride;
    UINT position_offset;
    UINT position_bytes;
    UINT normal_offset;
    UINT diffuse_offset;
    UINT specular_offset;
    UINT texcoord_offset[8];
    UINT texcoord_bytes[8];
    UINT texcoord_count;
    BOOL has_position;
    BOOL has_normal;
    BOOL has_diffuse;
    BOOL has_specular;
} D3D7FVFLayout;

static BOOL d3d7_decode_fvf(DWORD fvf, D3D7FVFLayout *layout,
        D9WGVertexElement *elements, UINT *element_count)
{
    static const BYTE tex_types[4] = {
        D3D9DECLTYPE_FLOAT2, D3D9DECLTYPE_FLOAT3,
        D3D9DECLTYPE_FLOAT4, D3D9DECLTYPE_FLOAT1
    };
    static const UINT tex_bytes[4] = { 8u, 12u, 16u, 4u };
    DWORD position = fvf & DDWG_FVF_POSITION_MASK_D3D7;
    UINT offset = 0;
    UINT count = 0;
    UINT index;

    ZeroMemory(layout, sizeof(*layout));
    if (fvf & DDWG_FVF_RESERVED0) return FALSE;

#define D3D7_PUSH_ELEMENT(kind, use, use_index) do { \
    if (!elements || count >= D3D7_MAX_VERTEX_ELEMENTS || offset > 0xffffu) \
        return FALSE; \
    elements[count].stream = 0; \
    elements[count].offset = (uint16_t)offset; \
    elements[count].type = (uint8_t)(kind); \
    elements[count].method = D3D9DECLMETHOD_DEFAULT; \
    elements[count].usage = (uint8_t)(use); \
    elements[count].usage_index = (uint8_t)(use_index); \
    ++count; \
} while (0)

    layout->position_offset = offset;
    if (position == DDWG_FVF_XYZ) {
        layout->has_position = TRUE;
        layout->position_bytes = 12u;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_POSITION, 0);
        offset += 12u;
    } else if (position == DDWG_FVF_XYZRHW) {
        layout->has_position = TRUE;
        layout->position_bytes = 16u;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT4, D3D9DECLUSAGE_POSITIONT, 0);
        offset += 16u;
    /* The advertised four-matrix vertex-blend limit covers XYZB1..XYZB4.
     * D3D7's XYZB5 is five float weights (not D3D8's indexed LASTBETA form),
     * so accepting it as blend indices would corrupt the following fields. */
    } else if (position >= DDWG_FVF_XYZB1 && position <= DDWG_FVF_XYZB4) {
        UINT blend_dwords = 1u + ((position - DDWG_FVF_XYZB1) >> 1);
        UINT weight_count = blend_dwords;
        layout->has_position = TRUE;
        layout->position_bytes = 12u + blend_dwords * 4u;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_POSITION, 0);
        offset += 12u;
        if (weight_count) {
            D3D7_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT1 + weight_count - 1u,
                    D3D9DECLUSAGE_BLENDWEIGHT, 0);
            offset += weight_count * 4u;
        }
    } else {
        return FALSE;
    }
    if (fvf & DDWG_FVF_NORMAL) {
        layout->has_normal = TRUE;
        layout->normal_offset = offset;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_FLOAT3, D3D9DECLUSAGE_NORMAL, 0);
        offset += 12u;
    }
    /* D3DFVF_RESERVED1 is a real reserved DWORD in D3DLVERTEX. It must stay
     * in the stride even though it is deliberately absent from the host FVF. */
    if (fvf & DDWG_FVF_RESERVED1_D3D7) offset += 4u;
    if (fvf & DDWG_FVF_DIFFUSE) {
        layout->has_diffuse = TRUE;
        layout->diffuse_offset = offset;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_D3DCOLOR, D3D9DECLUSAGE_COLOR, 0);
        offset += 4u;
    }
    if (fvf & DDWG_FVF_SPECULAR) {
        layout->has_specular = TRUE;
        layout->specular_offset = offset;
        D3D7_PUSH_ELEMENT(D3D9DECLTYPE_D3DCOLOR, D3D9DECLUSAGE_COLOR, 1);
        offset += 4u;
    }
    layout->texcoord_count = (fvf & DDWG_FVF_TEXCOUNT_MASK)
            >> DDWG_FVF_TEXCOUNT_SHIFT;
    if (layout->texcoord_count > 8u) return FALSE;
    for (index = 0; index < layout->texcoord_count; ++index) {
        UINT size_code = (fvf >> (16u + index * 2u)) & 3u;
        layout->texcoord_offset[index] = offset;
        layout->texcoord_bytes[index] = tex_bytes[size_code];
        D3D7_PUSH_ELEMENT(tex_types[size_code], D3D9DECLUSAGE_TEXCOORD,
                index);
        offset += tex_bytes[size_code];
    }
#undef D3D7_PUSH_ELEMENT

    layout->stride = offset;
    *element_count = count;
    return count != 0 && offset != 0;
}
